import test from 'node:test';
import assert from 'node:assert/strict';
import {readFile} from 'node:fs/promises';
import {createHash} from 'node:crypto';
import {createAtlasContextReader,resolveAtlasContextOverride} from '../../lib/geometry/prepared-atlas.mjs';
// Reduced real records generated by geometry/source-index-v2/context_override.py.
// Canonical scientific IDs and full expected scope output are retained.
const fixtures=JSON.parse(await readFile(new URL('../fixtures/source-context-overrides.json',import.meta.url),'utf8'));
for(const [name,fixture]of Object.entries(fixtures.cases))test(`source context matches independent scope resolver: ${name}`,()=>{
  assert.deepEqual(resolveAtlasContextOverride(fixture.unitId,fixture.descriptor,fixture.payload),fixture.expected);
});

test('partitioned context lookup verifies only its exact bucket and preserves missing anchor coverage',async()=>{
  const fixture=fixtures.cases.missing_anchor||Object.values(fixtures.cases).find(f=>f.expected.missingAnchorIds.length),prefix=fixture.unitId.slice(5,7),files=new Map(),sha=text=>createHash('sha256').update(text).digest('hex');
  const payload=JSON.stringify(fixture.payload),payloadFile={path:'context.json',sha256:sha(payload)};files.set('context.json',payload);
  const bucket=JSON.stringify({units:{[fixture.unitId]:fixture.descriptor},shards:{[fixture.descriptor.shardId]:payloadFile}});files.set('unit-index.json',bucket);
  const index=JSON.stringify({schemaVersion:'1.0.0',kind:'eigenquestions-source-context-index',coverage:{description:'Test bucket from reduced real source records'},unitIndex:{kind:'unit-hash-prefix',prefixLength:2,shards:{[prefix]:{path:'unit-index.json',sha256:sha(bucket)},ff:{path:'unused.json',sha256:'f'.repeat(64)}}}});files.set('index.json',index);
  const atlas={catalog:{},manifest:{files:{sourceContextIndex:{path:'index.json',sha256:sha(index)}}}},reads=[];
  const read=createAtlasContextReader(atlas,{base:'/fixture',readText:async path=>{const name=path.split('/').at(-1);reads.push(name);if(!files.has(name))throw new Error('Unexpected file '+name);return files.get(name);}});
  const result=await read(fixture.unitId);assert.deepEqual(reads,['index.json','unit-index.json','context.json']);assert.deepEqual(result.missingAnchorIds,fixture.expected.missingAnchorIds);assert.equal(result.attachmentOverridePolicy,fixtures.policy);assert.equal(result.coverage.directExportedRelationCount,fixture.expected.coverage.directExportedRelationCount);assert.match(result.coverage.description,/Zero exported/);
  files.set('unit-index.json',bucket+' ');await assert.rejects(createAtlasContextReader(atlas,{base:'/fixture',readText:async path=>files.get(path.split('/').at(-1))})(fixture.unitId),/checksum mismatch/);
});
